# Computing the static list once at startup, pseudocode
def build_resource_list(config_dir):
    return [
        {"uri": f"config://app/{f.name}", "name": f.name, "mimeType": "text/yaml"}
        for f in config_dir.glob("*.yaml")
    ]

RESOURCES = build_resource_list(CONFIG_DIR)  # computed once, reused every call

def test_static_list_is_stable():
    first = server.list_resources()
    second = server.list_resources()
    assert first == second

def test_every_listed_uri_reads_successfully():
    for entry in server.list_resources():
        result = server.read_resource(entry["uri"])
        assert result is not None

